export default {
    name: "userAudit",
    data() {
        return {
            pendingUsers: [],
            currentPage: 1,
            pageSize: 8,
            total: 0
        }
    },
    created() {
        this.getPendingUsers();
    },
    methods: {
        getPendingUsers() {
            this.$api.admin({
                url: 'getPendingUsers',
                method: 'get',
                params: {
                    page: this.currentPage,
                    nums: this.pageSize
                }
            }).then(res => {
                if (res.status_code === 1) {
                    this.pendingUsers = res.data.list;
                    this.total = res.data.count;
                } else {
                    this.$message.error(res.msg || '获取待审核用户失败');
                }
            }).catch(err => {
                console.error(err);
                this.$message.error('获取待审核用户失败');
            });
        },
        handleCurrentChange(val) {
            this.currentPage = val;
            this.getPendingUsers();
        },
        handleApprove(row) {
            this.$confirm('确认通过该用户的注册申请?', '提示', {
                confirmButtonText: '确定',
                cancelButtonText: '取消',
                type: 'success'
            }).then(() => {
                this.approveUser(row.id, true);
            }).catch(() => {
                // 取消操作
            });
        },
        handleReject(row) {
            this.$confirm('确认拒绝该用户的注册申请? 该操作将删除此用户的所有数据。', '警告', {
                confirmButtonText: '确定',
                cancelButtonText: '取消',
                type: 'warning'
            }).then(() => {
                this.approveUser(row.id, false);
            }).catch(() => {
                // 取消操作
            });
        },
        approveUser(userId, approved) {
            this.$api.admin({
                url: 'approveUser',
                method: 'get',
                params: {
                    id: userId,
                    approved: approved
                }
            }).then(res => {
                if (res.status_code === 1) {
                    this.$message({
                        type: 'success',
                        message: approved ? '已通过用户申请' : '已拒绝用户申请'
                    });
                    this.getPendingUsers(); // 刷新列表
                } else {
                    this.$message.error(res.msg || '操作失败');
                }
            }).catch(err => {
                console.error(err);
                this.$message.error('操作失败');
            });
        }
    }
}
